// MARK: - AppIconAsset.swift
// Embedded app logo provider ensuring the LockedIn icon renders reliably in all environments.

import AppKit
import SwiftUI

final class AppIconProvider {
    static let shared = AppIconProvider()

    let image: NSImage?

    private init() {
        // 1. Try Asset catalog
        if let img = NSImage(named: "AppLogo") ?? NSImage(named: "AppIcon") {
            self.image = img
            return
        }
        // 2. Try application icon
        if let appImg = NSApplication.shared.applicationIconImage, appImg.isValid && appImg.size.width > 0 {
            self.image = appImg
            return
        }
        // 3. Fallback to embedded PNG data
        if let data = Data(base64Encoded: AppIconProvider.embeddedBase64),
           let img = NSImage(data: data) {
            self.image = img
            return
        }
        self.image = nil
    }

    private static let embeddedBase64 = ""
}

struct AppIconView: View {
    var size: CGFloat = 28
    var cornerRadius: CGFloat = 6

    var body: some View {
        Group {
            if let img = AppIconProvider.shared.image {
                Image(nsImage: img)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
            } else {
                Image(systemName: "lock.shield.fill")
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .foregroundColor(.accentColor)
            }
        }
        .frame(width: size, height: size)
        .clipShape(RoundedRectangle(cornerRadius: cornerRadius, style: .continuous))
        .shadow(color: Color.black.opacity(0.12), radius: 2, x: 0, y: 1)
    }
}
